public async Task<IReadOnlyList<Invoice>> ListIssuedByCustomerAsync(int customerId, CancellationToken ct)
SELECT InvoiceId, CustomerId, Amount, IssuedUtc, DueUtc, Status FROM dbo.Invoice WHERE CustomerId = @customerId AND Status = 1
